import unittest
from solution import parse_count
class ParseTests(unittest.TestCase):
    def test_zero(self): self.assertEqual(parse_count("0"), 0)
    def test_decimal(self): self.assertEqual(parse_count("123"), 123)
    def test_reject_negative(self):
        with self.assertRaises(ValueError): parse_count("-2")
    def test_reject_noninteger(self):
        with self.assertRaises(ValueError): parse_count("1.5")
